option.value:
-- Flyway migration: V1_4_7__split_pending_totp_secret_lookup.sql -- Separate the pending-secret lookup (enrollment) from the active-secret lookup (login). -- -- BACKGROUND: -- V1_4_5 relaxed api_schema.get_totp_secret(uuid) to return BOTH pending and verified -- secrets so the enable flow could read the just-stored pending secret. Side effect: -- the login-time verifier (JooqTotpVerifier.verifyCode → get_totp_secret) then also -- accepted codes against a *pending* secret, i.e. before the user finished enrolment. -- -- FIX: -- - get_totp_secret(uuid) → reverts to ACTIVE secrets only (verified_at IS NOT NULL). -- Used by the login-time 2FA challenge (verifyCode). -- - get_pending_totp_secret(uuid) → NEW: PENDING secrets only (verified_at IS NULL). -- Used by the enable flow (verifySetupCode) to validate the -- first OTP before activation. -- -- SECURITY MODEL (unchanged): SECURITY DEFINER under owner_role, locked search_path, -- REVOKE ALL FROM PUBLIC then GRANT EXECUTE TO ${API_USER}, owned by owner_role. -- -- DEPENDENCIES: Read functions (V1_4_1), pending-lookup relaxation (V1_4_5)
-- ============================================================================ -- 1. GET TOTP SECRET (ACTIVE / verified secrets only — login-time verification) -- ============================================================================ CREATE OR REPLACE FUNCTION api_schema.get_totp_secret( p_user_id uuid ) RETURNS TABLE ( secret_key_encrypted bytea, algorithm varchar(10), period_seconds integer, digits integer ) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, private_schema AS $$ SELECT ts.secret_key_encrypted, ts.algorithm, ts.period_seconds, ts.digits FROM private_schema.totp_secrets ts WHERE ts.user_id = p_user_id AND ts.verified_at IS NOT NULL; $$;
COMMENT ON FUNCTION api_schema.get_totp_secret(uuid) IS 'Returns the encrypted TOTP secret and configuration for an ACTIVE 2FA enrollment ' '(verified_at IS NOT NULL). Used by the TOTP verifier adapter to validate codes during ' 'login. Pending (not-yet-verified) secrets are intentionally invisible here — use ' 'get_pending_totp_secret during enrollment. SECURITY DEFINER runs as owner_role.';
ALTER FUNCTION api_schema.get_totp_secret(uuid) OWNER TO owner_role; REVOKE ALL ON FUNCTION api_schema.get_totp_secret(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION api_schema.get_totp_secret(uuid) TO ${API_USER};
-- ============================================================================ -- 2. GET PENDING TOTP SECRET (PENDING secrets only — enrollment verification) -- ============================================================================ CREATE OR REPLACE FUNCTION api_schema.get_pending_totp_secret( p_user_id uuid ) RETURNS TABLE ( secret_key_encrypted bytea, algorithm varchar(10), period_seconds integer, digits integer ) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, private_schema AS $$ SELECT ts.secret_key_encrypted, ts.algorithm, ts.period_seconds, ts.digits FROM private_schema.totp_secrets ts WHERE ts.user_id = p_user_id AND ts.verified_at IS NULL; $$;
COMMENT ON FUNCTION api_schema.get_pending_totp_secret(uuid) IS 'Returns the encrypted TOTP secret for a PENDING enrollment (verified_at IS NULL). Used by ' 'the enable flow to validate the first OTP code before activating 2FA. SECURITY DEFINER ' 'runs as owner_role.';
ALTER FUNCTION api_schema.get_pending_totp_secret(uuid) OWNER TO owner_role; REVOKE ALL ON FUNCTION api_schema.get_pending_totp_secret(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION api_schema.get_pending_totp_secret(uuid) TO ${API_USER};

import java.awt.Desktop

plugins {
    id 'java'
    id 'jacoco'
    id 'com.google.protobuf' version '0.9.4'
}

group = 'com.oodesigns'
version = '1.0-SNAPSHOT'

java {
    toolchain {
        languageVersion = JavaLanguageVersion.of(26)
    }
}

repositories {
    mavenCentral()
}

dependencies {
    // Testing
    testImplementation platform('org.junit:junit-bom:6.1.0-M1')
    testImplementation 'org.junit.jupiter:junit-jupiter'
    testImplementation 'org.junit.jupiter:junit-jupiter-api'
    testImplementation 'org.junit.jupiter:junit-jupiter-engine'
    testRuntimeOnly 'org.junit.platform:junit-platform-launcher'
    testImplementation 'org.mockito:mockito-core:5.21.0'
    testImplementation 'org.mockito:mockito-junit-jupiter:5.21.0'
    testImplementation 'org.testcontainers:testcontainers:2.0.3'
    testImplementation 'org.testcontainers:testcontainers-postgresql:2.0.3'
    testImplementation 'org.testcontainers:testcontainers-junit-jupiter:2.0.3'
    testImplementation 'io.grpc:grpc-testing:1.68.0'

    // Logging - SLF4J with Logback implementation for tests
    testImplementation 'ch.qos.logback:logback-classic:1.5.23'

    // Database
    implementation 'org.jooq:jooq:3.20.10'
    implementation 'org.postgresql:postgresql:42.7.8'

    // gRPC / Protobuf
    implementation 'io.grpc:grpc-netty-shaded:1.68.0'
    implementation 'io.grpc:grpc-protobuf:1.68.0'
    implementation 'io.grpc:grpc-stub:1.68.0'
    implementation 'com.google.protobuf:protobuf-java:3.25.5'
    implementation 'javax.annotation:javax.annotation-api:1.3.2'

    // Main dependencies
    implementation 'jakarta.annotation:jakarta.annotation-api:2.1.1'
    implementation 'com.fasterxml.jackson.core:jackson-databind:2.18.0'
    implementation 'com.bucket4j:bucket4j_jdk17-core:8.15.0'
    implementation 'org.springframework.security:spring-security-crypto:7.0.2'
    implementation 'commons-logging:commons-logging:1.2'
    implementation 'io.jsonwebtoken:jjwt-api:0.12.1'
    runtimeOnly 'io.jsonwebtoken:jjwt-impl:0.12.1'
    runtimeOnly 'io.jsonwebtoken:jjwt-jackson:0.12.1'
}

// Configuration to resolve Mockito agent path
configurations {
    mockitoAgent
}

dependencies {
    mockitoAgent('org.mockito:mockito-core:5.14.1') { transitive = false }
}

protobuf {
    protoc {
        artifact = 'com.google.protobuf:protoc:3.25.5'
    }
    plugins {
        grpc {
            artifact = 'io.grpc:protoc-gen-grpc-java:1.68.0'
        }
    }
    generateProtoTasks {
        all()*.plugins {
            grpc {}
        }
    }
}

// Standard test task excludes integration tests - they require environment setup
test {
    useJUnitPlatform {
        excludeTags 'integration'
    }
    // Configure Mockito as a Java agent to enable inline-mock-maker
    jvmArgs += "-javaagent:${configurations.mockitoAgent.singleFile}"
    finalizedBy jacocoTestReport

}

tasks.register('integrationTest', Test) {
    testClassesDirs = sourceSets.test.output.classesDirs
    classpath = sourceSets.test.runtimeClasspath
    useJUnitPlatform {
        includeTags 'integration'
        excludeTags 'database'  // Exclude database tests from general integration tests
    }
    jvmArgs += "-javaagent:${configurations.mockitoAgent.singleFile}"
    shouldRunAfter test
}

tasks.register('databaseIntegrationTest', Test) {
    testClassesDirs = sourceSets.test.output.classesDirs
    classpath = sourceSets.test.runtimeClasspath
    useJUnitPlatform {
        includeTags 'database'
    }
    jvmArgs += "-javaagent:${configurations.mockitoAgent.singleFile}"
    shouldRunAfter test

    // Only run if database is available (check via environment variable or manual flag)
    final boolean includeDbTests = System.getenv('RUN_DATABASE_TESTS') == 'true' || findProperty('includeDbTests') != null
    onlyIf {
        includeDbTests
    }
}

jacocoTestReport {
    // Aggregate coverage across all test tiers (unit + integration). The database
    // tier is included automatically if it has been run (its .exec file will exist).
    dependsOn test, tasks.named('integrationTest')
    mustRunAfter tasks.named('databaseIntegrationTest')
    executionData fileTree(layout.buildDirectory.dir('jacoco')).include('*.exec')
    afterEvaluate {
        classDirectories.setFrom(files(classDirectories.files.collect { directory ->
            fileTree(dir: directory, exclude: [
                'com/oodesigns/cas/domain/service/Ports.class',
                'com/oodesigns/cas/infrastructure/config/DatabaseContextFactory.class',
                'com/oodesigns/cas/Main.class',
                'com/oodesigns/cas/infrastructure/grpc/proto/**'
            ])
        }))
    }
    reports {
        xml.required = true
        html.required = true
        csv.required = false
    }
    doLast {
        def reportPath = "${reports.html.outputLocation.get()}/index.html"
        if (!System.getenv("CI")) {
            def reportFile = new File(reportPath)
            if (reportFile.exists()) {
                try {
                    // Try using Java Desktop API first
                    if (Desktop.isDesktopSupported() && Desktop.getDesktop().isSupported(Desktop.Action.BROWSE)) {
                        Desktop.getDesktop().browse(reportFile.toURI())
                    } else {
                        // Fallback to command line tools
                        def os = System.getProperty("os.name").toLowerCase()
                        if (os.contains("windows")) {
                            new ProcessBuilder("cmd", "/c", "start", reportFile.absolutePath).start()
                        } else if (os.contains("mac")) {
                            new ProcessBuilder("open", reportFile.absolutePath).start()
                        } else if (os.contains("linux")) {
                            new ProcessBuilder("xdg-open", reportFile.absolutePath).start()
                        }
                    }
                } catch (Exception e) {
                    logger.warn("Could not automatically open report: ${e.message}")
                }
            }
        }
    }
}

jacocoTestCoverageVerification {
    // Verify against aggregated coverage from all executed test tiers so that
    // classes exercised only by integration tests (e.g. LoginRateLimiter,
    // TokenService) count toward the 100% line-coverage requirement.
    dependsOn test, tasks.named('integrationTest')
    mustRunAfter tasks.named('databaseIntegrationTest')
    executionData fileTree(layout.buildDirectory.dir('jacoco')).include('*.exec')
    afterEvaluate {
        classDirectories.setFrom(files(classDirectories.files.collect { directory ->
            fileTree(dir: directory, exclude: [
                'com/oodesigns/cas/domain/service/Ports.class',
                'com/oodesigns/cas/infrastructure/config/DatabaseContextFactory.class',
                'com/oodesigns/cas/Main.class',
                'com/oodesigns/cas/infrastructure/grpc/proto/**'
            ])
        }))
    }
    violationRules {
        rule {
            element = 'CLASS'
            includes = ['com.oodesigns.*']
            excludes = [
                'com.oodesigns.cas.domain.service.Ports',
                'com.oodesigns.cas.infrastructure.config.DatabaseContextFactory',
                'com.oodesigns.cas.Main',
                'com.oodesigns.cas.infrastructure.grpc.proto.*'
            ]

            limit {
                counter = 'LINE'
                value = 'COVEREDRATIO'
                minimum = 1.00
            }
        }
    }
}

