    public interface RefreshTokenStore {
        /**
         * Record a newly issued refresh token, starting a new token family.
         * Called after a successful login or 2FA verification.
         *
         * @param userId       the owner of the refresh token
         * @param refreshToken the raw refresh token (the implementation stores only its hash)
         */
        void issue(final UserId userId, final String refreshToken);

        /**
         * Atomically consume the presented refresh token and record its replacement within the
         * same family. Detects reuse of an already-rotated/revoked token and revokes the family.
         *
         * @param presentedToken   the raw refresh token supplied by the client
         * @param replacementToken the raw refresh token that replaces it on success
         * @return the outcome of the rotation attempt
         */
        RotationStatus rotate(final String presentedToken, final String replacementToken);

        /**
         * Outcome of a {@link #rotate} attempt.
         */
        enum RotationStatus {
            /** Token was current; it has been consumed and replaced within its family. */
            ROTATED,
            /** Token was already consumed/revoked — replay detected; the family was revoked. */
            REUSE_DETECTED,
            /** No stored token matched the presented hash. */
            NOT_FOUND,
            /** The stored token existed but had already expired. */
            EXPIRED
        }
    }
}

package com.oodesigns.cas.infrastructure.adapter;

import com.oodesigns.cas.domain.service.Ports;
import com.oodesigns.cas.domain.service.TotpCodeGenerator;
import com.oodesigns.cas.domain.value.BackupCode;
import com.oodesigns.cas.domain.value.KeyPassword;
import com.oodesigns.cas.domain.value.SecretFor2FA;
import com.oodesigns.cas.domain.value.TotpCode;
import com.oodesigns.cas.domain.value.UserId;
import java.util.List;
import java.util.Objects;
import java.util.Optional;
import java.util.UUID;
import org.jooq.DSLContext;
import org.jooq.Record;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.security.crypto.password.PasswordEncoder;

/**
 * JOOQ-based implementation of {@link Ports.TotpVerifier}.
 * <p>
 * Retrieves encrypted TOTP secrets from the database, decrypts them with on-demand key
 * material, verifies time-based OTP codes, and consumes backup codes atomically.
 */
public final class JooqTotpVerifier implements Ports.TotpVerifier {

    private final DSLContext dsl;
    private final TotpCodeGenerator totpCodeGenerator;
    private final PasswordEncoder passwordEncoder;
    private final KeySupplier keySupplier;
    private final String encryptionKeyId;

    public JooqTotpVerifier(final DSLContext dsl,
                            final Ports.Clock clock,
                            final KeySupplier keySupplier,
                            final String encryptionKeyId) {
        this(dsl, new TotpCodeGenerator(clock), new BCryptPasswordEncoder(), keySupplier, encryptionKeyId);
    }

    JooqTotpVerifier(final DSLContext dsl,
                     final TotpCodeGenerator totpCodeGenerator,
                     final PasswordEncoder passwordEncoder,
                     final KeySupplier keySupplier,
                     final String encryptionKeyId) {
        this.dsl = Objects.requireNonNull(dsl, "DSLContext cannot be null");
        this.totpCodeGenerator = Objects.requireNonNull(totpCodeGenerator, "TotpCodeGenerator cannot be null");
        this.passwordEncoder = Objects.requireNonNull(passwordEncoder, "PasswordEncoder cannot be null");
        this.keySupplier = Objects.requireNonNull(keySupplier, "KeySupplier cannot be null");
        this.encryptionKeyId = Objects.requireNonNull(encryptionKeyId, "Encryption key ID cannot be null");
    }

    @Override
    public boolean verifyCode(final UserId userId, final TotpCode totpCode) {
        return Optional.ofNullable(userId)
            .flatMap(id -> Optional.ofNullable(totpCode)
                .flatMap(code -> loadSecret(id).map(secret -> totpCodeGenerator.verify(secret, code.value()))))
            .orElse(false);
    }

    @Override
    public boolean verifyBackupCode(final UserId userId, final BackupCode backupCode) {
        return Optional.ofNullable(userId)
            .flatMap(id -> Optional.ofNullable(backupCode)
                .flatMap(code -> consumeMatchingBackupCode(id, code)))
            .orElse(false);
    }

    @Override
    public boolean isTotpEnabled(final UserId userId) {
        return Optional.ofNullable(userId)
            .flatMap(id -> Routines.getTotpStatus(dsl, id.value()).map(record -> true))
            .orElse(false);
    }

    private Optional<SecretFor2FA> loadSecret(final UserId userId) {
        return Routines.getTotpSecret(dsl, userId.value())
            .flatMap(record -> encryptionKey().map(key -> decryptSecret(record, key)))
            .filter(Objects::nonNull)
            .map(SecretFor2FA::of);
    }

    private Optional<Boolean> consumeMatchingBackupCode(final UserId userId, final BackupCode backupCode) {
        final String[] hashes = Routines.findUnusedBackupCodeHashes(dsl, userId.value());
        for (final String hash : hashes) {
            if (passwordEncoder.matches(backupCode.getCode(), hash) && Routines.consumeBackupCode(dsl, userId.value(), hash)) {
                Routines.markTotpLastUsed(dsl, userId.value());
                return Optional.of(true);
            }
        }
        return Optional.empty();
    }

    private Optional<KeyPassword> encryptionKey() {
        return keySupplier.getPassword(encryptionKeyId);
    }

    private String decryptSecret(final TotpSecretRecord record, final KeyPassword keyPassword) {
        try (keyPassword) {
            return TotpSecretCipher.decrypt(record.secretKeyEncrypted(), keyPassword);
        }
    }

    /**
     * Hand-written shim mirroring generated jOOQ routines for the required API calls.
     */
    private static final class Routines {
        static Optional<TotpSecretRecord> getTotpSecret(final DSLContext ctx, final UUID userId) {
            return ctx.fetchOptional("SELECT * FROM api_schema.get_totp_secret(?)", userId)
                .map(record -> new TotpSecretRecord(
                    record.get("secret_key_encrypted", byte[].class),
                    record.get("algorithm", String.class),
                    record.get("period_seconds", Integer.class),
                    record.get("digits", Integer.class)
                ));
        }

        static Optional<TotpStatusRecord> getTotpStatus(final DSLContext ctx, final UUID userId) {
            return ctx.fetchOptional("SELECT * FROM api_schema.get_totp_status(?)", userId)
                .map(record -> new TotpStatusRecord(record.get("user_id", UUID.class)));
        }

        static String[] findUnusedBackupCodeHashes(final DSLContext ctx, final UUID userId) {
            return Optional.ofNullable(ctx.fetchOne("SELECT api_schema.find_unused_backup_code_hashes(?)", userId))
                .map(record -> record.get(0, String[].class))
                .orElseGet(() -> new String[0]);
        }

        static boolean consumeBackupCode(final DSLContext ctx, final UUID userId, final String codeHash) {
            return Optional.ofNullable(ctx.fetchOne("SELECT api_schema.consume_backup_code(?, ?)", userId, codeHash))
                .map(record -> record.get(0, Boolean.class))
                .orElse(false);
        }

        static boolean markTotpLastUsed(final DSLContext ctx, final UUID userId) {
            return Optional.ofNullable(ctx.fetchOne("SELECT api_schema.mark_totp_last_used(?)", userId))
                .map(record -> record.get(0, Boolean.class))
                .orElse(false);
        }
    }

    private record TotpSecretRecord(byte[] secretKeyEncrypted, String algorithm, Integer periodSeconds, Integer digits) {
    }

    private record TotpStatusRecord(UUID userId) {
    }
}

package com.oodesigns.cas.infrastructure.adapter;

import com.oodesigns.cas.domain.service.Ports;
import com.oodesigns.cas.domain.service.TotpCodeGenerator;
import com.oodesigns.cas.domain.value.BackupCode;
import com.oodesigns.cas.domain.value.KeyPassword;
import com.oodesigns.cas.domain.value.SecretFor2FA;
import com.oodesigns.cas.domain.value.TotpCode;
import com.oodesigns.cas.domain.value.UserId;
import java.util.List;
import java.util.Objects;
import java.util.Optional;
import java.util.UUID;
import org.jooq.DSLContext;
import org.jooq.Record;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.security.crypto.password.PasswordEncoder;

/**
 * JOOQ-based implementation of {@link Ports.TotpVerifier}.
 * <p>
 * Retrieves encrypted TOTP secrets from the database, decrypts them with on-demand key
 * material, verifies time-based OTP codes, and consumes backup codes atomically.
 */
public final class JooqTotpVerifier implements Ports.TotpVerifier {

    private final DSLContext dsl;
    private final TotpCodeGenerator totpCodeGenerator;
    private final PasswordEncoder passwordEncoder;
    private final KeySupplier keySupplier;
    private final String encryptionKeyId;

    public JooqTotpVerifier(final DSLContext dsl,
                            final Ports.Clock clock,
                            final KeySupplier keySupplier,
                            final String encryptionKeyId) {
        this(dsl, new TotpCodeGenerator(clock), new BCryptPasswordEncoder(), keySupplier, encryptionKeyId);
    }

    JooqTotpVerifier(final DSLContext dsl,
                     final TotpCodeGenerator totpCodeGenerator,
                     final PasswordEncoder passwordEncoder,
                     final KeySupplier keySupplier,
                     final String encryptionKeyId) {
        this.dsl = Objects.requireNonNull(dsl, "DSLContext cannot be null");
        this.totpCodeGenerator = Objects.requireNonNull(totpCodeGenerator, "TotpCodeGenerator cannot be null");
        this.passwordEncoder = Objects.requireNonNull(passwordEncoder, "PasswordEncoder cannot be null");
        this.keySupplier = Objects.requireNonNull(keySupplier, "KeySupplier cannot be null");
        this.encryptionKeyId = Objects.requireNonNull(encryptionKeyId, "Encryption key ID cannot be null");
    }

    @Override
    public boolean verifyCode(final UserId userId, final TotpCode totpCode) {
        return verifyAgainst(userId, totpCode, Routines::getTotpSecret);
    }

    @Override
    public boolean verifySetupCode(final UserId userId, final TotpCode totpCode) {
        return verifyAgainst(userId, totpCode, Routines::getPendingTotpSecret);
    }

    private boolean verifyAgainst(final UserId userId, final TotpCode totpCode, final SecretLoader loader) {
        return Optional.ofNullable(userId)
            .flatMap(id -> Optional.ofNullable(totpCode)
                .flatMap(code -> loadSecret(id, loader).map(secret -> totpCodeGenerator.verify(secret, code.value()))))
            .orElse(false);
    }

    @Override
    public boolean verifyBackupCode(final UserId userId, final BackupCode backupCode) {
        return Optional.ofNullable(userId)
            .flatMap(id -> Optional.ofNullable(backupCode)
                .flatMap(code -> consumeMatchingBackupCode(id, code)))
            .orElse(false);
    }

    @Override
    public boolean isTotpEnabled(final UserId userId) {
        return Optional.ofNullable(userId)
            .flatMap(id -> Routines.getTotpStatus(dsl, id.value()).map(record -> true))
            .orElse(false);
    }

    private Optional<SecretFor2FA> loadSecret(final UserId userId, final SecretLoader loader) {
        return loader.load(dsl, userId.value())
            .flatMap(record -> encryptionKey().map(key -> decryptSecret(record, key)))
            .filter(Objects::nonNull)
            .map(SecretFor2FA::of);
    }

    private Optional<Boolean> consumeMatchingBackupCode(final UserId userId, final BackupCode backupCode) {
        final String[] hashes = Routines.findUnusedBackupCodeHashes(dsl, userId.value());
        for (final String hash : hashes) {
            if (passwordEncoder.matches(backupCode.getCode(), hash) && Routines.consumeBackupCode(dsl, userId.value(), hash)) {
                Routines.markTotpLastUsed(dsl, userId.value());
                return Optional.of(true);
            }
        }
        return Optional.empty();
    }

    private Optional<KeyPassword> encryptionKey() {
        return keySupplier.getPassword(encryptionKeyId);
    }

    private String decryptSecret(final TotpSecretRecord record, final KeyPassword keyPassword) {
        try (keyPassword) {
            return TotpSecretCipher.decrypt(record.secretKeyEncrypted(), keyPassword);
        }
    }

    /**
     * Hand-written shim mirroring generated jOOQ routines for the required API calls.
     */
    private static final class Routines {
        static Optional<TotpSecretRecord> getTotpSecret(final DSLContext ctx, final UUID userId) {
            return mapSecret(ctx.fetchOptional("SELECT * FROM api_schema.get_totp_secret(?)", userId));
        }

        static Optional<TotpSecretRecord> getPendingTotpSecret(final DSLContext ctx, final UUID userId) {
            return mapSecret(ctx.fetchOptional("SELECT * FROM api_schema.get_pending_totp_secret(?)", userId));
        }

        private static Optional<TotpSecretRecord> mapSecret(final Optional<Record> row) {
            return row.map(record -> new TotpSecretRecord(
                record.get("secret_key_encrypted", byte[].class),
                record.get("algorithm", String.class),
                record.get("period_seconds", Integer.class),
                record.get("digits", Integer.class)
            ));
        }

        static Optional<TotpStatusRecord> getTotpStatus(final DSLContext ctx, final UUID userId) {
            return ctx.fetchOptional("SELECT * FROM api_schema.get_totp_status(?)", userId)
                .map(record -> new TotpStatusRecord(record.get("user_id", UUID.class)));
        }

        static String[] findUnusedBackupCodeHashes(final DSLContext ctx, final UUID userId) {
            return Optional.ofNullable(ctx.fetchOne("SELECT api_schema.find_unused_backup_code_hashes(?)", userId))
                .map(record -> record.get(0, String[].class))
                .orElseGet(() -> new String[0]);
        }

        static boolean consumeBackupCode(final DSLContext ctx, final UUID userId, final String codeHash) {
            return Optional.ofNullable(ctx.fetchOne("SELECT api_schema.consume_backup_code(?, ?)", userId, codeHash))
                .map(record -> record.get(0, Boolean.class))
                .orElse(false);
        }

        static boolean markTotpLastUsed(final DSLContext ctx, final UUID userId) {
            return Optional.ofNullable(ctx.fetchOne("SELECT api_schema.mark_totp_last_used(?)", userId))
                .map(record -> record.get(0, Boolean.class))
                .orElse(false);
        }
    }

    private record TotpSecretRecord(byte[] secretKeyEncrypted, String algorithm, Integer periodSeconds, Integer digits) {
    }

    private record TotpStatusRecord(UUID userId) {
    }

    /**
     * Strategy for loading an encrypted TOTP secret record — either the active secret
     * ({@code get_totp_secret}) for login, or the pending secret ({@code get_pending_totp_secret})
     * for enrolment.
     */
    @FunctionalInterface
    private interface SecretLoader {
        Optional<TotpSecretRecord> load(DSLContext ctx, UUID userId);
    }
}

package com.oodesigns.cas.infrastructure.adapter;

import com.oodesigns.cas.domain.service.TotpCodeGenerator;
import com.oodesigns.cas.domain.value.BackupCode;
import com.oodesigns.cas.domain.value.KeyPassword;
import com.oodesigns.cas.domain.value.SecretFor2FA;
import com.oodesigns.cas.domain.value.TotpCode;
import com.oodesigns.cas.domain.value.UserId;
import java.security.SecureRandom;
import java.time.Instant;
import java.util.Optional;
import java.util.UUID;
import org.jooq.DSLContext;
import org.jooq.Record;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.security.crypto.password.PasswordEncoder;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.verifyNoInteractions;
import static org.mockito.Mockito.when;

@SuppressWarnings("SqlResolve")
@ExtendWith(MockitoExtension.class)
class JooqTotpVerifierTest {

    private static final String TEST_KEY = "0123456789ABCDEF0123456789ABCDEF";
    private static final String ENCRYPTION_KEY_ID = "TOTP_ENCRYPTION_KEY";
    private static final String SECRET = "JBSWY3DPEHPK3PXP";
    private static final Instant FIXED_NOW = Instant.parse("2026-08-10T12:00:00Z");

    @Mock
    private DSLContext dslContext;

    @Mock
    private KeySupplier keySupplier;

    private PasswordEncoder passwordEncoder;
    private TotpCodeGenerator totpCodeGenerator;
    private JooqTotpVerifier verifier;

    @BeforeEach
    void setUp() {
        passwordEncoder = new BCryptPasswordEncoder();
        totpCodeGenerator = new TotpCodeGenerator(() -> FIXED_NOW);
        verifier = new JooqTotpVerifier(dslContext, totpCodeGenerator, passwordEncoder, keySupplier, ENCRYPTION_KEY_ID);
    }

    @Test
    void constructorRejectsNullDsl() {
        assertThrows(NullPointerException.class,
            () -> new JooqTotpVerifier(null, totpCodeGenerator, passwordEncoder, keySupplier, ENCRYPTION_KEY_ID));
    }

    @Test
    void publicConstructorInitialisesAdapter() {
        new JooqTotpVerifier(dslContext, () -> FIXED_NOW, keySupplier, ENCRYPTION_KEY_ID);
    }

    @Test
    void verifyCodeReturnsTrueForMatchingSecret() {
        final UUID userId = UUID.randomUUID();
        final String code = totpCodeGenerator.generate(SecretFor2FA.of(SECRET));
        when(keySupplier.getPassword(ENCRYPTION_KEY_ID)).thenReturn(Optional.of(KeyPassword.of(TEST_KEY)));
        when(dslContext.fetchOptional("SELECT * FROM api_schema.get_totp_secret(?)", userId))
            .thenReturn(Optional.of(secretRecord()));

        assertTrue(verifier.verifyCode(UserId.of(userId), TotpCode.of(code)));
        verify(dslContext).fetchOptional("SELECT * FROM api_schema.get_totp_secret(?)", userId);
    }

    @Test
    void verifyBackupCodeReturnsFalseWhenNoUnusedHashesExist() {
        final UUID userId = UUID.randomUUID();
        when(dslContext.fetchOne("SELECT api_schema.find_unused_backup_code_hashes(?)", userId))
            .thenReturn(null);

        assertFalse(verifier.verifyBackupCode(UserId.of(userId), BackupCode.of("ABCD-EFGH-IJKL-MNPQ")));
        verify(dslContext, never()).fetchOne("SELECT api_schema.consume_backup_code(?, ?)", userId, "unused");
    }

    @Test
    void verifyBackupCodeReturnsFalseWhenHashesExistButNoneMatch() {
        // Hashes present but none match → covers the passwordEncoder.matches()=false branch
        final UUID userId = UUID.randomUUID();
        final BackupCode attempted = BackupCode.of("AAAA-BBBB-CCCC-DDDD");
        final String hashOfDifferentCode = passwordEncoder.encode("ZZZZ-YYYY-XXXX-WWWV");
        when(dslContext.fetchOne("SELECT api_schema.find_unused_backup_code_hashes(?)", userId))
            .thenReturn(backupHashesRecord(hashOfDifferentCode));

        assertFalse(verifier.verifyBackupCode(UserId.of(userId), attempted));
        verify(dslContext, never()).fetchOne(
                org.mockito.ArgumentMatchers.eq("SELECT api_schema.consume_backup_code(?, ?)"),
                org.mockito.ArgumentMatchers.any(), org.mockito.ArgumentMatchers.any());
    }

    @Test
    void verifyBackupCodeReturnsFalseWhenConsumeBackupCodeFailsConcurrently() {
        // Hash matches but consumeBackupCode returns false (concurrent consumption race)
        // → covers the matches()=true but consumeBackupCode()=false branch
        final UUID userId = UUID.randomUUID();
        final BackupCode backupCode = BackupCode.of("ABCD-EFGH-IJKL-MNPQ");
        final String hash = passwordEncoder.encode(backupCode.getCode());
        when(dslContext.fetchOne("SELECT api_schema.find_unused_backup_code_hashes(?)", userId))
            .thenReturn(backupHashesRecord(hash));
        when(dslContext.fetchOne("SELECT api_schema.consume_backup_code(?, ?)", userId, hash))
            .thenReturn(falseRecord());

        assertFalse(verifier.verifyBackupCode(UserId.of(userId), backupCode));
        verify(dslContext, never()).fetchOne("SELECT api_schema.mark_totp_last_used(?)", userId);
    }

    @Test
    void verifyBackupCodeReturnsFalseWhenInputsAreNull() {
        assertFalse(verifier.verifyCode(null, TotpCode.of("123456")));
        assertFalse(verifier.verifyCode(UserId.of(UUID.randomUUID()), null));
    }

    @Test
    void verifyBackupCodeConsumesMatchingHashAndMarksLastUsed() {
        final UUID userId = UUID.randomUUID();
        final BackupCode backupCode = BackupCode.of("ABCD-EFGH-IJKL-MNPQ");
        final String hash = passwordEncoder.encode(backupCode.getCode());
        when(dslContext.fetchOne("SELECT api_schema.find_unused_backup_code_hashes(?)", userId))
            .thenReturn(backupHashesRecord(hash));
        when(dslContext.fetchOne("SELECT api_schema.consume_backup_code(?, ?)", userId, hash))
            .thenReturn(trueRecord());
        when(dslContext.fetchOne("SELECT api_schema.mark_totp_last_used(?)", userId))
            .thenReturn(trueRecord());

        assertTrue(verifier.verifyBackupCode(UserId.of(userId), backupCode));
        verify(dslContext).fetchOne("SELECT api_schema.consume_backup_code(?, ?)", userId, hash);
        verify(dslContext).fetchOne("SELECT api_schema.mark_totp_last_used(?)", userId);
    }


    @Test
    void isTotpEnabledReturnsTrueWhenStatusRowExists() {
        final UUID userId = UUID.randomUUID();
        when(dslContext.fetchOptional("SELECT * FROM api_schema.get_totp_status(?)", userId))
            .thenReturn(Optional.of(statusRecord(userId)));

        assertTrue(verifier.isTotpEnabled(UserId.of(userId)));
    }

    @Test
    void isTotpEnabledReturnsFalseWhenStatusRowMissing() {
        final UUID userId = UUID.randomUUID();
        when(dslContext.fetchOptional("SELECT * FROM api_schema.get_totp_status(?)", userId))
            .thenReturn(Optional.empty());

        assertFalse(verifier.isTotpEnabled(UserId.of(userId)));
    }

    @Test
    void isTotpEnabledReturnsFalseWhenUserIdIsNull() {
        assertFalse(verifier.isTotpEnabled(null));
    }

    private Record secretRecord() {
        final byte[] ciphertext = TotpSecretCipher.encrypt(
            SECRET,
            KeyPassword.of(TEST_KEY),
            new SecureRandom()
        );
        return mock(Record.class, invocation -> {
            final Object[] args = invocation.getArguments();
            if (args.length == 2 && "secret_key_encrypted".equals(args[0])) {
                return ciphertext;
            }
            if (args.length == 2 && "algorithm".equals(args[0])) {
                return "SHA1";
            }
            if (args.length == 2 && "period_seconds".equals(args[0])) {
                return 30;
            }
            if (args.length == 2 && "digits".equals(args[0])) {
                return 6;
            }
            return null;
        });
    }

    private Record backupHashesRecord(final String hash) {
        return mock(Record.class, invocation -> {
            final Object[] args = invocation.getArguments();
            if (args.length == 2 && args[0] instanceof Integer && ((Integer) args[0]) == 0) {
                return new String[]{hash};
            }
            return null;
        });
    }

    private Record trueRecord() {
        return mock(Record.class, invocation -> {
            final Object[] args = invocation.getArguments();
            if (args.length == 2 && args[0] instanceof Integer && ((Integer) args[0]) == 0) {
                return Boolean.TRUE;
            }
            return null;
        });
    }

    private Record falseRecord() {
        return mock(Record.class, invocation -> {
            final Object[] args = invocation.getArguments();
            if (args.length == 2 && args[0] instanceof Integer && ((Integer) args[0]) == 0) {
                return Boolean.FALSE;
            }
            return null;
        });
    }

    private Record statusRecord(final UUID userId) {
        return mock(Record.class, invocation -> {
            final Object[] args = invocation.getArguments();
            if (args.length == 2 && "user_id".equals(args[0])) {
                return userId;
            }
            return null;
        });
    }
}

