    private PasswordEncoder passwordEncoder;
    private TotpCodeGenerator totpCodeGenerator;
    private JooqTotpVerifier verifier;

    @BeforeEach
    void setUp() {
        passwordEncoder = new BCryptPasswordEncoder();
        totpCodeGenerator = new TotpCodeGenerator(() -> FIXED_NOW);
        verifier = new JooqTotpVerifier(dslContext, totpCodeGenerator, passwordEncoder, keySupplier, ENCRYPTION_KEY_ID);
    }

    @Test
    void constructorRejectsNullDsl() {
        assertThrows(NullPointerException.class,
            () -> new JooqTotpVerifier(null, totpCodeGenerator, passwordEncoder, keySupplier, ENCRYPTION_KEY_ID));
    }

    @Test
    void publicConstructorInitialisesAdapter() {
        new JooqTotpVerifier(dslContext, () -> FIXED_NOW, keySupplier, ENCRYPTION_KEY_ID);
    }

    @Test
    void verifyCodeReturnsTrueForMatchingSecret() {
        final UUID userId = UUID.randomUUID();
        final String code = totpCodeGenerator.generate(SecretFor2FA.of(SECRET));
        when(keySupplier.getPassword(ENCRYPTION_KEY_ID)).thenReturn(Optional.of(KeyPassword.of(TEST_KEY)));
        when(dslContext.fetchOptional("SELECT * FROM api_schema.get_totp_secret(?)", userId))
            .thenReturn(Optional.of(secretRecord()));

        assertTrue(verifier.verifyCode(UserId.of(userId), TotpCode.of(code)));
        verify(dslContext).fetchOptional("SELECT * FROM api_schema.get_totp_secret(?)", userId);
    }

    @Test
    void verifySetupCodeReturnsTrueForMatchingPendingSecret() {
        final UUID userId = UUID.randomUUID();
        final String code = totpCodeGenerator.generate(SecretFor2FA.of(SECRET));
        when(keySupplier.getPassword(ENCRYPTION_KEY_ID)).thenReturn(Optional.of(KeyPassword.of(TEST_KEY)));
        when(dslContext.fetchOptional("SELECT * FROM api_schema.get_pending_totp_secret(?)", userId))
            .thenReturn(Optional.of(secretRecord()));

        assertTrue(verifier.verifySetupCode(UserId.of(userId), TotpCode.of(code)));
        // Enrolment must NOT consult the active-secret function.
        verify(dslContext).fetchOptional("SELECT * FROM api_schema.get_pending_totp_secret(?)", userId);
        verify(dslContext, never()).fetchOptional("SELECT * FROM api_schema.get_totp_secret(?)", userId);
    }

    @Test
    void verifySetupCodeReturnsFalseWhenInputsAreNull() {
        assertFalse(verifier.verifySetupCode(null, TotpCode.of("123456")));
        assertFalse(verifier.verifySetupCode(UserId.of(UUID.randomUUID()), null));
    }

    @Test
    void verifyBackupCodeReturnsFalseWhenNoUnusedHashesExist() {
        final UUID userId = UUID.randomUUID();
        when(dslContext.fetchOne("SELECT api_schema.find_unused_backup_code_hashes(?)", userId))
            .thenReturn(null);

        assertFalse(verifier.verifyBackupCode(UserId.of(userId), BackupCode.of("ABCD-EFGH-IJKL-MNPQ")));
        verify(dslContext, never()).fetchOne("SELECT api_schema.consume_backup_code(?, ?)", userId, "unused");
    }

    @Test
    void verifyBackupCodeReturnsFalseWhenHashesExistButNoneMatch() {
        // Hashes present but none match → covers the passwordEncoder.matches()=false branch
        final UUID userId = UUID.randomUUID();
        final BackupCode attempted = BackupCode.of("AAAA-BBBB-CCCC-DDDD");
        final String hashOfDifferentCode = passwordEncoder.encode("ZZZZ-YYYY-XXXX-WWWV");
        when(dslContext.fetchOne("SELECT api_schema.find_unused_backup_code_hashes(?)", userId))
            .thenReturn(backupHashesRecord(hashOfDifferentCode));

        assertFalse(verifier.verifyBackupCode(UserId.of(userId), attempted));
        verify(dslContext, never()).fetchOne(
                org.mockito.ArgumentMatchers.eq("SELECT api_schema.consume_backup_code(?, ?)"),
                org.mockito.ArgumentMatchers.any(), org.mockito.ArgumentMatchers.any());
    }

    @Test
    void verifyBackupCodeReturnsFalseWhenConsumeBackupCodeFailsConcurrently() {
        // Hash matches but consumeBackupCode returns false (concurrent consumption race)
        // → covers the matches()=true but consumeBackupCode()=false branch
        final UUID userId = UUID.randomUUID();
        final BackupCode backupCode = BackupCode.of("ABCD-EFGH-IJKL-MNPQ");
        final String hash = passwordEncoder.encode(backupCode.getCode());
        when(dslContext.fetchOne("SELECT api_schema.find_unused_backup_code_hashes(?)", userId))
            .thenReturn(backupHashesRecord(hash));
        when(dslContext.fetchOne("SELECT api_schema.consume_backup_code(?, ?)", userId, hash))
            .thenReturn(falseRecord());

        assertFalse(verifier.verifyBackupCode(UserId.of(userId), backupCode));
        verify(dslContext, never()).fetchOne("SELECT api_schema.mark_totp_last_used(?)", userId);
    }

    @Test
    void verifyBackupCodeReturnsFalseWhenInputsAreNull() {
        assertFalse(verifier.verifyCode(null, TotpCode.of("123456")));
        assertFalse(verifier.verifyCode(UserId.of(UUID.randomUUID()), null));
    }

    @Test
    void verifyBackupCodeConsumesMatchingHashAndMarksLastUsed() {
        final UUID userId = UUID.randomUUID();
        final BackupCode backupCode = BackupCode.of("ABCD-EFGH-IJKL-MNPQ");
        final String hash = passwordEncoder.encode(backupCode.getCode());
        when(dslContext.fetchOne("SELECT api_schema.find_unused_backup_code_hashes(?)", userId))
            .thenReturn(backupHashesRecord(hash));
        when(dslContext.fetchOne("SELECT api_schema.consume_backup_code(?, ?)", userId, hash))
            .thenReturn(trueRecord());
        when(dslContext.fetchOne("SELECT api_schema.mark_totp_last_used(?)", userId))
            .thenReturn(trueRecord());

        assertTrue(verifier.verifyBackupCode(UserId.of(userId), backupCode));
        verify(dslContext).fetchOne("SELECT api_schema.consume_backup_code(?, ?)", userId, hash);
        verify(dslContext).fetchOne("SELECT api_schema.mark_totp_last_used(?)", userId);
    }


    @Test
    void isTotpEnabledReturnsTrueWhenStatusRowExists() {
        final UUID userId = UUID.randomUUID();
        when(dslContext.fetchOptional("SELECT * FROM api_schema.get_totp_status(?)", userId))
            .thenReturn(Optional.of(statusRecord(userId)));

        assertTrue(verifier.isTotpEnabled(UserId.of(userId)));
    }

    @Test
    void isTotpEnabledReturnsFalseWhenStatusRowMissing() {
        final UUID userId = UUID.randomUUID();
        when(dslContext.fetchOptional("SELECT * FROM api_schema.get_totp_status(?)", userId))
            .thenReturn(Optional.empty());

        assertFalse(verifier.isTotpEnabled(UserId.of(userId)));
    }

    @Test
    void isTotpEnabledReturnsFalseWhenUserIdIsNull() {
        assertFalse(verifier.isTotpEnabled(null));
    }

    private Record secretRecord() {
        final byte[] ciphertext = TotpSecretCipher.encrypt(
            SECRET,
            KeyPassword.of(TEST_KEY),
            new SecureRandom()
        );
        return mock(Record.class, invocation -> {
            final Object[] args = invocation.getArguments();
            if (args.length == 2 && "secret_key_encrypted".equals(args[0])) {
                return ciphertext;
            }
            if (args.length == 2 && "algorithm".equals(args[0])) {
                return "SHA1";
            }
            if (args.length == 2 && "period_seconds".equals(args[0])) {
                return 30;
            }
            if (args.length == 2 && "digits".equals(args[0])) {
                return 6;
            }
            return null;
        });
    }

    private Record backupHashesRecord(final String hash) {
        return mock(Record.class, invocation -> {
            final Object[] args = invocation.getArguments();
            if (args.length == 2 && args[0] instanceof Integer && ((Integer) args[0]) == 0) {
                return new String[]{hash};
            }
            return null;
        });
    }

    private Record trueRecord() {
        return mock(Record.class, invocation -> {
            final Object[] args = invocation.getArguments();
            if (args.length == 2 && args[0] instanceof Integer && ((Integer) args[0]) == 0) {
                return Boolean.TRUE;
            }
            return null;
        });
    }

    private Record falseRecord() {
        return mock(Record.class, invocation -> {
            final Object[] args = invocation.getArguments();
            if (args.length == 2 && args[0] instanceof Integer && ((Integer) args[0]) == 0) {
                return Boolean.FALSE;
            }
            return null;
        });
    }

    private Record statusRecord(final UUID userId) {
        return mock(Record.class, invocation -> {
            final Object[] args = invocation.getArguments();
            if (args.length == 2 && "user_id".equals(args[0])) {
                return userId;
            }
            return null;
        });
    }
}

package com.oodesigns.cas.infrastructure.adapter;

import com.oodesigns.cas.domain.service.Ports;
import com.oodesigns.cas.domain.value.BackupCode;
import com.oodesigns.cas.domain.value.TotpCode;
import com.oodesigns.cas.domain.value.UserId;
import java.util.Objects;
import java.util.Optional;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

/**
 * In-memory mock implementation of {@link Ports.TotpVerifier} for integration tests.
 * <p>
 * Tracks enabled users and counts verification attempts, while allowing tests to preconfigure
 * accepted OTP and backup-code values.
 */
public class MockTotpVerifier implements Ports.TotpVerifier {

    private final Set<UserId> enabledUsers = ConcurrentHashMap.newKeySet();
    private final Set<String> validTotpCodes = ConcurrentHashMap.newKeySet();
    private final Set<String> validBackupCodes = ConcurrentHashMap.newKeySet();
    private final AtomicInteger verificationAttempts = new AtomicInteger();
    private final AtomicInteger backupAttempts = new AtomicInteger();

    @Override
    public boolean verifyCode(final UserId userId, final TotpCode totpCode) {
        verificationAttempts.incrementAndGet();
        if (userId == null || totpCode == null) {
            return false;
        }
        return enabledUsers.contains(userId) && validTotpCodes.contains(totpCode.getCode());
    }

    @Override
    public boolean verifyBackupCode(final UserId userId, final BackupCode backupCode) {
        backupAttempts.incrementAndGet();
        if (userId == null || backupCode == null) {
            return false;
        }
        final String normalized = backupCode.getCode();
        return enabledUsers.contains(userId) && validBackupCodes.remove(normalized);
    }

    @Override
    public boolean isTotpEnabled(final UserId userId) {
        return userId != null && enabledUsers.contains(userId);
    }

    public void enable(final UserId userId) {
        enabledUsers.add(requireUserId(userId));
    }

    public void disable(final UserId userId) {
        enabledUsers.remove(requireUserId(userId));
    }

    public void registerValidTotpCode(final String code) {
        validTotpCodes.add(requireCode(code));
    }

    public void registerValidBackupCode(final String code) {
        validBackupCodes.add(requireCode(code));
    }

    public boolean isRegisteredTotpCode(final String code) {
        return validTotpCodes.contains(requireCode(code));
    }

    public boolean isRegisteredBackupCode(final String code) {
        return validBackupCodes.contains(requireCode(code));
    }

    public int getVerificationAttemptCount() {
        return verificationAttempts.get();
    }

    public int getBackupAttemptCount() {
        return backupAttempts.get();
    }

    public void clear() {
        enabledUsers.clear();
        validTotpCodes.clear();
        validBackupCodes.clear();
        verificationAttempts.set(0);
        backupAttempts.set(0);
    }

    private static UserId requireUserId(final UserId userId) {
        return Objects.requireNonNull(userId, "User ID cannot be null");
    }

    private static String requireCode(final String code) {
        return Objects.requireNonNull(code, "Code cannot be null");
    }
}

package com.oodesigns.cas.infrastructure.adapter;

import com.oodesigns.cas.domain.service.Ports;
import com.oodesigns.cas.domain.value.BackupCode;
import com.oodesigns.cas.domain.value.TotpCode;
import com.oodesigns.cas.domain.value.UserId;
import java.util.Objects;
import java.util.Optional;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

/**
 * In-memory mock implementation of {@link Ports.TotpVerifier} for integration tests.
 * <p>
 * Tracks enabled users and counts verification attempts, while allowing tests to preconfigure
 * accepted OTP and backup-code values.
 */
public class MockTotpVerifier implements Ports.TotpVerifier {

    private final Set<UserId> enabledUsers = ConcurrentHashMap.newKeySet();
    private final Set<String> validTotpCodes = ConcurrentHashMap.newKeySet();
    private final Set<String> validBackupCodes = ConcurrentHashMap.newKeySet();
    private final AtomicInteger verificationAttempts = new AtomicInteger();
    private final AtomicInteger backupAttempts = new AtomicInteger();

    @Override
    public boolean verifyCode(final UserId userId, final TotpCode totpCode) {
        verificationAttempts.incrementAndGet();
        if (userId == null || totpCode == null) {
            return false;
        }
        return enabledUsers.contains(userId) && validTotpCodes.contains(totpCode.getCode());
    }

    @Override
    public boolean verifySetupCode(final UserId userId, final TotpCode totpCode) {
        // Enrolment happens before activation, so — unlike verifyCode — this does not require
        // the user to be enabled; it validates against the pending secret only.
        verificationAttempts.incrementAndGet();
        if (userId == null || totpCode == null) {
            return false;
        }
        return validTotpCodes.contains(totpCode.getCode());
    }

    @Override
    public boolean verifyBackupCode(final UserId userId, final BackupCode backupCode) {
        backupAttempts.incrementAndGet();
        if (userId == null || backupCode == null) {
            return false;
        }
        final String normalized = backupCode.getCode();
        return enabledUsers.contains(userId) && validBackupCodes.remove(normalized);
    }

    @Override
    public boolean isTotpEnabled(final UserId userId) {
        return userId != null && enabledUsers.contains(userId);
    }

    public void enable(final UserId userId) {
        enabledUsers.add(requireUserId(userId));
    }

    public void disable(final UserId userId) {
        enabledUsers.remove(requireUserId(userId));
    }

    public void registerValidTotpCode(final String code) {
        validTotpCodes.add(requireCode(code));
    }

    public void registerValidBackupCode(final String code) {
        validBackupCodes.add(requireCode(code));
    }

    public boolean isRegisteredTotpCode(final String code) {
        return validTotpCodes.contains(requireCode(code));
    }

    public boolean isRegisteredBackupCode(final String code) {
        return validBackupCodes.contains(requireCode(code));
    }

    public int getVerificationAttemptCount() {
        return verificationAttempts.get();
    }

    public int getBackupAttemptCount() {
        return backupAttempts.get();
    }

    public void clear() {
        enabledUsers.clear();
        validTotpCodes.clear();
        validBackupCodes.clear();
        verificationAttempts.set(0);
        backupAttempts.set(0);
    }

    private static UserId requireUserId(final UserId userId) {
        return Objects.requireNonNull(userId, "User ID cannot be null");
    }

    private static String requireCode(final String code) {
        return Objects.requireNonNull(code, "Code cannot be null");
    }
}

package com.oodesigns.cas.infrastructure.adapter;

import com.oodesigns.cas.domain.value.BackupCode;
import com.oodesigns.cas.domain.value.TotpCode;
import com.oodesigns.cas.domain.value.UserId;
import java.util.UUID;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

class MockTotpVerifierTest {

    @Test
    void verifierChecksEnabledUsersAndConsumesBackupCodes() {
        final MockTotpVerifier verifier = new MockTotpVerifier();
        final UserId userId = UserId.of(UUID.randomUUID());

        verifier.enable(userId);
        verifier.registerValidTotpCode("123456");
        verifier.registerValidBackupCode("ABCD-EFGH-IJKL-MNPQ");

        assertTrue(verifier.isTotpEnabled(userId));
        assertTrue(verifier.verifyCode(userId, TotpCode.of("123456")));
        assertTrue(verifier.verifyBackupCode(userId, BackupCode.of("ABCD-EFGH-IJKL-MNPQ")));
        assertFalse(verifier.verifyBackupCode(userId, BackupCode.of("ABCD-EFGH-IJKL-MNPQ")));
        assertTrue(verifier.getVerificationAttemptCount() >= 1);
        assertTrue(verifier.getBackupAttemptCount() >= 2);
    }

    @Test
    void verifierHandlesNullInputsAndClear() {
        final MockTotpVerifier verifier = new MockTotpVerifier();

        assertFalse(verifier.verifyCode(null, null));
        assertFalse(verifier.verifyBackupCode(null, null));
        assertFalse(verifier.isTotpEnabled(null));

        verifier.clear();
        assertEquals(0, verifier.getVerificationAttemptCount());
        assertEquals(0, verifier.getBackupAttemptCount());
    }
}

package com.oodesigns.cas.infrastructure.adapter;

import com.oodesigns.cas.domain.value.BackupCode;
import com.oodesigns.cas.domain.value.TotpCode;
import com.oodesigns.cas.domain.value.UserId;
import java.util.UUID;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

class MockTotpVerifierTest {

    @Test
    void verifierChecksEnabledUsersAndConsumesBackupCodes() {
        final MockTotpVerifier verifier = new MockTotpVerifier();
        final UserId userId = UserId.of(UUID.randomUUID());

        verifier.enable(userId);
        verifier.registerValidTotpCode("123456");
        verifier.registerValidBackupCode("ABCD-EFGH-IJKL-MNPQ");

        assertTrue(verifier.isTotpEnabled(userId));
        assertTrue(verifier.verifyCode(userId, TotpCode.of("123456")));
        assertTrue(verifier.verifyBackupCode(userId, BackupCode.of("ABCD-EFGH-IJKL-MNPQ")));
        assertFalse(verifier.verifyBackupCode(userId, BackupCode.of("ABCD-EFGH-IJKL-MNPQ")));
        assertTrue(verifier.getVerificationAttemptCount() >= 1);
        assertTrue(verifier.getBackupAttemptCount() >= 2);
    }

    @Test
    void verifierHandlesNullInputsAndClear() {
        final MockTotpVerifier verifier = new MockTotpVerifier();

        assertFalse(verifier.verifyCode(null, null));
        assertFalse(verifier.verifySetupCode(null, null));
        assertFalse(verifier.verifyBackupCode(null, null));
        assertFalse(verifier.isTotpEnabled(null));

        verifier.clear();
        assertEquals(0, verifier.getVerificationAttemptCount());
        assertEquals(0, verifier.getBackupAttemptCount());
    }

    @Test
    void verifySetupCodeAcceptsPendingCodeWithoutRequiringEnabledUser() {
        final MockTotpVerifier verifier = new MockTotpVerifier();
        final UserId userId = UserId.of(UUID.randomUUID());
        verifier.registerValidTotpCode("654321");

        // Not enabled yet (enrolment in progress) — verifyCode rejects, verifySetupCode accepts.
        assertFalse(verifier.verifyCode(userId, TotpCode.of("654321")));
        assertTrue(verifier.verifySetupCode(userId, TotpCode.of("654321")));
        assertFalse(verifier.verifySetupCode(userId, TotpCode.of("000000")));
    }
}

package com.oodesigns.cas.integration.database;

import com.oodesigns.cas.application.command.DisableReason;
import com.oodesigns.cas.domain.service.Ports;
import com.oodesigns.cas.domain.service.TotpCodeGenerator;
import com.oodesigns.cas.domain.value.BackupCode;
import com.oodesigns.cas.domain.value.KeyPassword;
import com.oodesigns.cas.domain.value.SecretFor2FA;
import com.oodesigns.cas.domain.value.TotpCode;
import com.oodesigns.cas.domain.value.UserId;
import com.oodesigns.cas.infrastructure.adapter.JooqTotpSetupProvider;
import com.oodesigns.cas.infrastructure.adapter.JooqTotpStatusReader;
import com.oodesigns.cas.infrastructure.adapter.JooqTotpVerifier;
import com.oodesigns.cas.infrastructure.adapter.KeySupplier;
import com.oodesigns.cas.infrastructure.config.DatabaseConfig;
import com.oodesigns.cas.infrastructure.config.DatabaseContextFactory;
import com.oodesigns.cas.util.file.FileLoaderProviderFactory;
import com.oodesigns.cas.util.properties.EnvironmentVariableTransformer;
import com.oodesigns.cas.util.properties.PropertiesReader;
import java.time.Instant;
import java.util.List;
import java.util.Optional;
import java.util.UUID;
import org.jooq.DSLContext;
import org.jooq.Record;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Assumptions;
import org.junit.jupiter.api.Tag;
import org.junit.jupiter.api.Test;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Database integration tests for the TOTP migration and adapters.
 * <p>
 * Uses the real PostgreSQL database and the hand-written JOOQ adapters so the 2FA
 * setup, verification, and status flow are exercised end to end.
 */
@SuppressWarnings({"SqlResolve", "FieldCanBeLocal"})
@Tag("database")
@Tag("integration")
class TotpDatabaseIntegrationTest {

    private static final String TEST_TOTP_KEY = "0123456789ABCDEF0123456789ABCDEF";
    private static final Instant FIXED_NOW = Instant.parse("2026-08-10T12:00:00Z");

    private DatabaseConfig databaseConfig;
    private DSLContext dslContext;
    private DSLContext adminDsl;
    private UserId createdUserId;

    @BeforeEach
    void setUp() {
        Assumptions.assumeTrue(isDatabaseAvailable(), "Live PostgreSQL database is not available");

        final PropertiesReader propertiesReader = new PropertiesReader(
            "application.properties",
            new EnvironmentVariableTransformer(),
            FileLoaderProviderFactory.defaultProvider()
        );
        databaseConfig = new DatabaseConfig(propertiesReader);
        dslContext = DatabaseContextFactory.create(databaseConfig);
        adminDsl = createAdminDsl();
    }

    /**
     * Privileged connection for test fixtures and row-level verification.
     * The application connection uses the restricted API role, which (by design)
     * cannot read or write private_schema tables directly.
     */
    private DSLContext createAdminDsl() {
        final String adminUser = System.getenv().getOrDefault("POSTGRES_USER", "postgres");
        final String adminPassword = System.getenv().getOrDefault("POSTGRES_PASSWORD", "postgres");
        final String jdbcUrl = String.format("jdbc:postgresql://%s:%d/%s",
            databaseConfig.getHost(), databaseConfig.getPort(), databaseConfig.getDatabaseName());
        try {
            final java.sql.Connection connection =
                java.sql.DriverManager.getConnection(jdbcUrl, adminUser, adminPassword);
            return org.jooq.impl.DSL.using(connection, org.jooq.SQLDialect.POSTGRES);
        } catch (final java.sql.SQLException e) {
            throw new IllegalStateException("Could not open admin fixture connection", e);
        }
    }

    @AfterEach
    void tearDown() {
        if (createdUserId != null) {
            adminDsl.execute("DELETE FROM private_schema.users WHERE user_id = ?", createdUserId.value());
        }
        createdUserId = null;
    }

    @Test
    void migrationCreatesTotpTablesAndFunctions() {
        assertTrue(tableExists("totp_secrets"));
        assertTrue(tableExists("backup_codes"));

        assertTrue(functionExists("get_totp_status"));
        assertTrue(functionExists("get_totp_secret"));
        assertTrue(functionExists("find_unused_backup_code_hashes"));
        assertTrue(functionExists("mark_totp_last_used"));
        assertTrue(functionExists("store_totp_secret"));
        assertTrue(functionExists("enable_totp"));
        assertTrue(functionExists("disable_totp"));
        assertTrue(functionExists("insert_backup_codes"));
        assertTrue(functionExists("consume_backup_code"));
    }

    @Test
    void setupEnableVerifyAndDisableRoundTripsAgainstDatabase() {
        final UserId userId = createTemporaryUser();
        final Ports.Clock clock = () -> FIXED_NOW;
        final KeySupplier keySupplier = ignoredKeyId -> Optional.of(KeyPassword.of(TEST_TOTP_KEY));

        final JooqTotpSetupProvider setupProvider = new JooqTotpSetupProvider(dslContext, keySupplier, "TOTP_ENCRYPTION_KEY");
        final JooqTotpStatusReader statusReader = new JooqTotpStatusReader(dslContext);
        final JooqTotpVerifier verifier = new JooqTotpVerifier(dslContext, clock, keySupplier, "TOTP_ENCRYPTION_KEY");
        final TotpCodeGenerator codeGenerator = new TotpCodeGenerator(clock);

        final String secret = setupProvider.generateSecret(userId);
        assertNotNull(secret);
        assertEquals(1, totpSecretRowCount(userId));
        assertTrue(statusReader.check2FAStatus(userId).isEmpty());
        assertFalse(verifier.isTotpEnabled(userId));

        final String otp = codeGenerator.generate(SecretFor2FA.of(secret));
        assertFalse(verifier.verifyCode(userId, TotpCode.of(otp)));

        assertTrue(setupProvider.enableTotp(userId));
        assertTrue(statusReader.check2FAStatus(userId).isPresent());
        assertTrue(verifier.isTotpEnabled(userId));
        assertTrue(verifier.verifyCode(userId, TotpCode.of(otp)));

        final List<BackupCode> backupCodes = setupProvider.generateBackupCodes(userId);
        assertEquals(backupCodeGeneratorDefaultCount(), backupCodes.size());
        assertEquals(backupCodes.size(), backupCodeRowCount(userId));

        final BackupCode firstBackupCode = backupCodes.getFirst();
        assertTrue(verifier.verifyBackupCode(userId, firstBackupCode));
        assertFalse(verifier.verifyBackupCode(userId, firstBackupCode));
        assertEquals(1, usedBackupCodeRowCount(userId));
        assertTrue(lastUsedAtIsPopulated(userId));

        assertTrue(setupProvider.disableTotp(userId, DisableReason.USER_REQUESTED));
        assertTrue(statusReader.check2FAStatus(userId).isEmpty());
        assertFalse(verifier.isTotpEnabled(userId));
        assertEquals(0, totpSecretRowCount(userId));
        assertEquals(0, backupCodeRowCount(userId));
    }

    @Test
    void setupProviderCanReEnrollAfterDisable() {
        final UserId userId = createTemporaryUser();
        final KeySupplier keySupplier = ignoredKeyId -> Optional.of(KeyPassword.of(TEST_TOTP_KEY));
        final JooqTotpSetupProvider setupProvider = new JooqTotpSetupProvider(dslContext, keySupplier, "TOTP_ENCRYPTION_KEY");
        final JooqTotpStatusReader statusReader = new JooqTotpStatusReader(dslContext);

        final String firstSecret = setupProvider.generateSecret(userId);
        assertNotNull(firstSecret);
        assertTrue(setupProvider.enableTotp(userId));
        assertTrue(statusReader.check2FAStatus(userId).isPresent());

        assertTrue(setupProvider.disableTotp(userId, DisableReason.USER_REQUESTED));
        assertTrue(statusReader.check2FAStatus(userId).isEmpty());

        final String secondSecret = setupProvider.generateSecret(userId);
        assertNotNull(secondSecret);
        assertNotEquals(firstSecret, secondSecret);
        assertEquals(1, totpSecretRowCount(userId));
        assertTrue(statusReader.check2FAStatus(userId).isEmpty());
    }

    private UserId createTemporaryUser() {
        final UUID userId = UUID.randomUUID();
        final String username = "totp_db_" + userId.toString().substring(0, 8);
        final UUID adminRoleId = adminRoleId();
        final String passwordHash = new BCryptPasswordEncoder().encode("TemporaryPassword123!");

        adminDsl.execute(
            "INSERT INTO private_schema.users (user_id, username, password_hash, role_id) VALUES (?, ?, ?, ?)",
            userId,
            username,
            passwordHash,
            adminRoleId
        );

        createdUserId = UserId.of(userId);
        return createdUserId;
    }

    private UUID adminRoleId() {
        final Record record = adminDsl.fetchOne(
            "SELECT role_id FROM private_schema.roles WHERE name = ?",
            "admin"
        );
        assertNotNull(record, "Admin role should exist in seeded data");
        return record.get("role_id", UUID.class);
    }

    private boolean tableExists(final String tableName) {
        // pg_catalog is privilege-independent; information_schema hides tables the
        // restricted API role has no privileges on (by design).
        final Record record = dslContext.fetchOne(
            "SELECT EXISTS (SELECT 1 FROM pg_catalog.pg_tables WHERE schemaname = 'private_schema' AND tablename = ?)",
            tableName
        );
        return record != null && Boolean.TRUE.equals(record.get(0, Boolean.class));
    }

    private boolean functionExists(final String functionName) {
        final Record record = dslContext.fetchOne(
            "SELECT EXISTS (SELECT 1 FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_namespace n ON p.pronamespace = n.oid WHERE n.nspname = 'api_schema' AND p.proname = ?)",
            functionName
        );
        return record != null && Boolean.TRUE.equals(record.get(0, Boolean.class));
    }

    private int totpSecretRowCount(final UserId userId) {
        return rowCount("SELECT COUNT(*) FROM private_schema.totp_secrets WHERE user_id = ?", userId.value());
    }

    private int backupCodeRowCount(final UserId userId) {
        return rowCount("SELECT COUNT(*) FROM private_schema.backup_codes WHERE user_id = ?", userId.value());
    }

    private int usedBackupCodeRowCount(final UserId userId) {
        return rowCount("SELECT COUNT(*) FROM private_schema.backup_codes WHERE user_id = ? AND used_at IS NOT NULL", userId.value());
    }

    private boolean lastUsedAtIsPopulated(final UserId userId) {
        final Record record = adminDsl.fetchOne(
            "SELECT last_used_at FROM private_schema.totp_secrets WHERE user_id = ?",
            userId.value()
        );
        return record != null && record.get("last_used_at") != null;
    }

    private int rowCount(final String sql, final Object bindValue) {
        final Record record = adminDsl.fetchOne(sql, bindValue);
        assertNotNull(record, "Query should return a row");
        final Number count = record.get(0, Number.class);
        return count == null ? 0 : count.intValue();
    }

    private boolean isDatabaseAvailable() {
        try {
            final PropertiesReader propertiesReader = new PropertiesReader(
                "application.properties",
                new EnvironmentVariableTransformer(),
                FileLoaderProviderFactory.defaultProvider()
            );
            final DatabaseConfig config = new DatabaseConfig(propertiesReader);
            DatabaseContextFactory.create(config);
            return true;
        } catch (final RuntimeException e) {
            return false;
        }
    }

    private int backupCodeGeneratorDefaultCount() {
        return 10;
    }
}

package com.oodesigns.cas.integration.database;

import com.oodesigns.cas.application.command.DisableReason;
import com.oodesigns.cas.domain.service.Ports;
import com.oodesigns.cas.domain.service.TotpCodeGenerator;
import com.oodesigns.cas.domain.value.BackupCode;
import com.oodesigns.cas.domain.value.KeyPassword;
import com.oodesigns.cas.domain.value.SecretFor2FA;
import com.oodesigns.cas.domain.value.TotpCode;
import com.oodesigns.cas.domain.value.UserId;
import com.oodesigns.cas.infrastructure.adapter.JooqTotpSetupProvider;
import com.oodesigns.cas.infrastructure.adapter.JooqTotpStatusReader;
import com.oodesigns.cas.infrastructure.adapter.JooqTotpVerifier;
import com.oodesigns.cas.infrastructure.adapter.KeySupplier;
import com.oodesigns.cas.infrastructure.config.DatabaseConfig;
import com.oodesigns.cas.infrastructure.config.DatabaseContextFactory;
import com.oodesigns.cas.util.file.FileLoaderProviderFactory;
import com.oodesigns.cas.util.properties.EnvironmentVariableTransformer;
import com.oodesigns.cas.util.properties.PropertiesReader;
import java.time.Instant;
import java.util.List;
import java.util.Optional;
import java.util.UUID;
import org.jooq.DSLContext;
import org.jooq.Record;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Assumptions;
import org.junit.jupiter.api.Tag;
import org.junit.jupiter.api.Test;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Database integration tests for the TOTP migration and adapters.
 * <p>
 * Uses the real PostgreSQL database and the hand-written JOOQ adapters so the 2FA
 * setup, verification, and status flow are exercised end to end.
 */
@SuppressWarnings({"SqlResolve", "FieldCanBeLocal"})
@Tag("database")
@Tag("integration")
class TotpDatabaseIntegrationTest {

    private static final String TEST_TOTP_KEY = "0123456789ABCDEF0123456789ABCDEF";
    private static final Instant FIXED_NOW = Instant.parse("2026-08-10T12:00:00Z");

    private DatabaseConfig databaseConfig;
    private DSLContext dslContext;
    private DSLContext adminDsl;
    private UserId createdUserId;

    @BeforeEach
    void setUp() {
        Assumptions.assumeTrue(isDatabaseAvailable(), "Live PostgreSQL database is not available");

        final PropertiesReader propertiesReader = new PropertiesReader(
            "application.properties",
            new EnvironmentVariableTransformer(),
            FileLoaderProviderFactory.defaultProvider()
        );
        databaseConfig = new DatabaseConfig(propertiesReader);
        dslContext = DatabaseContextFactory.create(databaseConfig);
        adminDsl = createAdminDsl();
    }

    /**
     * Privileged connection for test fixtures and row-level verification.
     * The application connection uses the restricted API role, which (by design)
     * cannot read or write private_schema tables directly.
     */
    private DSLContext createAdminDsl() {
        final String adminUser = System.getenv().getOrDefault("POSTGRES_USER", "postgres");
        final String adminPassword = System.getenv().getOrDefault("POSTGRES_PASSWORD", "postgres");
        final String jdbcUrl = String.format("jdbc:postgresql://%s:%d/%s",
            databaseConfig.getHost(), databaseConfig.getPort(), databaseConfig.getDatabaseName());
        try {
            final java.sql.Connection connection =
                java.sql.DriverManager.getConnection(jdbcUrl, adminUser, adminPassword);
            return org.jooq.impl.DSL.using(connection, org.jooq.SQLDialect.POSTGRES);
        } catch (final java.sql.SQLException e) {
            throw new IllegalStateException("Could not open admin fixture connection", e);
        }
    }

    @AfterEach
    void tearDown() {
        if (createdUserId != null) {
            adminDsl.execute("DELETE FROM private_schema.users WHERE user_id = ?", createdUserId.value());
        }
        createdUserId = null;
    }

    @Test
    void migrationCreatesTotpTablesAndFunctions() {
        assertTrue(tableExists("totp_secrets"));
        assertTrue(tableExists("backup_codes"));

        assertTrue(functionExists("get_totp_status"));
        assertTrue(functionExists("get_totp_secret"));
        assertTrue(functionExists("get_pending_totp_secret"));
        assertTrue(functionExists("find_unused_backup_code_hashes"));
        assertTrue(functionExists("mark_totp_last_used"));
        assertTrue(functionExists("store_totp_secret"));
        assertTrue(functionExists("enable_totp"));
        assertTrue(functionExists("disable_totp"));
        assertTrue(functionExists("insert_backup_codes"));
        assertTrue(functionExists("consume_backup_code"));
    }

    @Test
    void setupEnableVerifyAndDisableRoundTripsAgainstDatabase() {
        final UserId userId = createTemporaryUser();
        final Ports.Clock clock = () -> FIXED_NOW;
        final KeySupplier keySupplier = ignoredKeyId -> Optional.of(KeyPassword.of(TEST_TOTP_KEY));

        final JooqTotpSetupProvider setupProvider = new JooqTotpSetupProvider(dslContext, keySupplier, "TOTP_ENCRYPTION_KEY");
        final JooqTotpStatusReader statusReader = new JooqTotpStatusReader(dslContext);
        final JooqTotpVerifier verifier = new JooqTotpVerifier(dslContext, clock, keySupplier, "TOTP_ENCRYPTION_KEY");
        final TotpCodeGenerator codeGenerator = new TotpCodeGenerator(clock);

        final String secret = setupProvider.generateSecret(userId);
        assertNotNull(secret);
        assertEquals(1, totpSecretRowCount(userId));
        assertTrue(statusReader.check2FAStatus(userId).isEmpty());
        assertFalse(verifier.isTotpEnabled(userId));

        final String otp = codeGenerator.generate(SecretFor2FA.of(secret));
        // Login-time verification must NOT accept a code against a pending (not-yet-enabled) secret,
        // but the enrolment path (verifySetupCode) must accept it against the pending secret.
        assertFalse(verifier.verifyCode(userId, TotpCode.of(otp)));
        assertTrue(verifier.verifySetupCode(userId, TotpCode.of(otp)));

        assertTrue(setupProvider.enableTotp(userId));
        assertTrue(statusReader.check2FAStatus(userId).isPresent());
        assertTrue(verifier.isTotpEnabled(userId));
        assertTrue(verifier.verifyCode(userId, TotpCode.of(otp)));

        final List<BackupCode> backupCodes = setupProvider.generateBackupCodes(userId);
        assertEquals(backupCodeGeneratorDefaultCount(), backupCodes.size());
        assertEquals(backupCodes.size(), backupCodeRowCount(userId));

        final BackupCode firstBackupCode = backupCodes.getFirst();
        assertTrue(verifier.verifyBackupCode(userId, firstBackupCode));
        assertFalse(verifier.verifyBackupCode(userId, firstBackupCode));
        assertEquals(1, usedBackupCodeRowCount(userId));
        assertTrue(lastUsedAtIsPopulated(userId));

        assertTrue(setupProvider.disableTotp(userId, DisableReason.USER_REQUESTED));
        assertTrue(statusReader.check2FAStatus(userId).isEmpty());
        assertFalse(verifier.isTotpEnabled(userId));
        assertEquals(0, totpSecretRowCount(userId));
        assertEquals(0, backupCodeRowCount(userId));
    }

    @Test
    void setupProviderCanReEnrollAfterDisable() {
        final UserId userId = createTemporaryUser();
        final KeySupplier keySupplier = ignoredKeyId -> Optional.of(KeyPassword.of(TEST_TOTP_KEY));
        final JooqTotpSetupProvider setupProvider = new JooqTotpSetupProvider(dslContext, keySupplier, "TOTP_ENCRYPTION_KEY");
        final JooqTotpStatusReader statusReader = new JooqTotpStatusReader(dslContext);

        final String firstSecret = setupProvider.generateSecret(userId);
        assertNotNull(firstSecret);
        assertTrue(setupProvider.enableTotp(userId));
        assertTrue(statusReader.check2FAStatus(userId).isPresent());

        assertTrue(setupProvider.disableTotp(userId, DisableReason.USER_REQUESTED));
        assertTrue(statusReader.check2FAStatus(userId).isEmpty());

        final String secondSecret = setupProvider.generateSecret(userId);
        assertNotNull(secondSecret);
        assertNotEquals(firstSecret, secondSecret);
        assertEquals(1, totpSecretRowCount(userId));
        assertTrue(statusReader.check2FAStatus(userId).isEmpty());
    }

    private UserId createTemporaryUser() {
        final UUID userId = UUID.randomUUID();
        final String username = "totp_db_" + userId.toString().substring(0, 8);
        final UUID adminRoleId = adminRoleId();
        final String passwordHash = new BCryptPasswordEncoder().encode("TemporaryPassword123!");

        adminDsl.execute(
            "INSERT INTO private_schema.users (user_id, username, password_hash, role_id) VALUES (?, ?, ?, ?)",
            userId,
            username,
            passwordHash,
            adminRoleId
        );

        createdUserId = UserId.of(userId);
        return createdUserId;
    }

    private UUID adminRoleId() {
        final Record record = adminDsl.fetchOne(
            "SELECT role_id FROM private_schema.roles WHERE name = ?",
            "admin"
        );
        assertNotNull(record, "Admin role should exist in seeded data");
        return record.get("role_id", UUID.class);
    }

    private boolean tableExists(final String tableName) {
        // pg_catalog is privilege-independent; information_schema hides tables the
        // restricted API role has no privileges on (by design).
        final Record record = dslContext.fetchOne(
            "SELECT EXISTS (SELECT 1 FROM pg_catalog.pg_tables WHERE schemaname = 'private_schema' AND tablename = ?)",
            tableName
        );
        return record != null && Boolean.TRUE.equals(record.get(0, Boolean.class));
    }

    private boolean functionExists(final String functionName) {
        final Record record = dslContext.fetchOne(
            "SELECT EXISTS (SELECT 1 FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_namespace n ON p.pronamespace = n.oid WHERE n.nspname = 'api_schema' AND p.proname = ?)",
            functionName
        );
        return record != null && Boolean.TRUE.equals(record.get(0, Boolean.class));
    }

    private int totpSecretRowCount(final UserId userId) {
        return rowCount("SELECT COUNT(*) FROM private_schema.totp_secrets WHERE user_id = ?", userId.value());
    }

    private int backupCodeRowCount(final UserId userId) {
        return rowCount("SELECT COUNT(*) FROM private_schema.backup_codes WHERE user_id = ?", userId.value());
    }

    private int usedBackupCodeRowCount(final UserId userId) {
        return rowCount("SELECT COUNT(*) FROM private_schema.backup_codes WHERE user_id = ? AND used_at IS NOT NULL", userId.value());
    }

    private boolean lastUsedAtIsPopulated(final UserId userId) {
        final Record record = adminDsl.fetchOne(
            "SELECT last_used_at FROM private_schema.totp_secrets WHERE user_id = ?",
            userId.value()
        );
        return record != null && record.get("last_used_at") != null;
    }

    private int rowCount(final String sql, final Object bindValue) {
        final Record record = adminDsl.fetchOne(sql, bindValue);
        assertNotNull(record, "Query should return a row");
        final Number count = record.get(0, Number.class);
        return count == null ? 0 : count.intValue();
    }

    private boolean isDatabaseAvailable() {
        try {
            final PropertiesReader propertiesReader = new PropertiesReader(
                "application.properties",
                new EnvironmentVariableTransformer(),
                FileLoaderProviderFactory.defaultProvider()
            );
            final DatabaseConfig config = new DatabaseConfig(propertiesReader);
            DatabaseContextFactory.create(config);
            return true;
        } catch (final RuntimeException e) {
            return false;
        }
    }

    private int backupCodeGeneratorDefaultCount() {
        return 10;
    }
}
